    const cards=state.passengers.map((p,i)=>`<section class="passenger-card"><div class="passenger-card-head"><span><b>${i+1}</b><strong>Voyageur ${i+1}</strong></span><em>Siège ${state.selectedSeats[i]}</em></div><div class="form-grid premium-form"><div class="field wide"><label>Prénom et nom *</label><input class="control" data-passenger-field="name" data-passenger-index="${i}" value="${p.name}" required></div><div class="field"><label>Téléphone international *</label><input class="control" data-passenger-field="phone" data-passenger-index="${i}" value="${p.phone}" required></div><div class="field"><label>Email — optionnel</label><input class="control" type="email" data-passenger-field="email" data-passenger-index="${i}" value="${p.email}"></div>${international?`<div class="field"><label>Type de document *</label><select class="control" data-passenger-field="documentType" data-passenger-index="${i}"><option>Passeport</option><option>CNI</option><option>Carte consulaire</option></select></div><div class="field"><label>Numéro du document *</label><input class="control" data-passenger-field="documentNumber" data-passenger-index="${i}" value="${p.documentNumber}" required></div><div class="field"><label>Nationalité *</label><input class="control" data-passenger-field="nationality" data-passenger-index="${i}" value="${p.nationality}" required></div><div class="field"><label>Date de naissance *</label><input class="control" type="date" data-passenger-field="birthDate" data-passenger-index="${i}" value="${p.birthDate}" required></div>`:""}</div></section>`).join("");
    return `${head(`<button class="btn btn-ghost" data-sale-step="1">Changer le voyage</button>`)}${saleProgress(3,"Informations voyageurs")}<div class="checkout-layout"><section class="panel checkout-main"><div class="checkout-title"><span class="section-kicker">${international?"L1 internationale":"L2/L3 nationale"} · ${state.passengerCount} voyageur${state.passengerCount>1?"s":""}</span><h2>Renseigner chaque voyageur</h2><p>${international?"Identité, document, nationalité et naissance sont obligatoires pour le manifeste frontière.":"Le nom et le téléphone sont obligatoires pour chaque billet."}</p></div>${cards}<div class="field wide"><label class="check"><input type="checkbox" id="counter-final-sale" checked> L’acheteur confirme le caractère définitif de la vente au guichet</label></div><div class="checkout-actions"><button class="btn btn-ghost" data-sale-step="1">Retour aux places</button><button class="btn btn-primary" data-sale-next="4">Continuer vers le paiement →</button></div></section>${journeySummary()}</div>`;
