    return `${head(`<button class="btn btn-ghost" data-sale-step="3">Modifier le passager</button>`)}${saleProgress(4,"Encaissement")}<div class="checkout-layout"><section class="panel checkout-main"><div class="checkout-title"><span class="section-kicker">Encaissement guichet</span><h2>Choisir le moyen de paiement</h2><p>Le règlement peut être effectué en espèces, par Mobile Money ou avec le solde mini-wallet du passager.</p></div><div class="payment-methods">${[["cash","Espèces","Saisir le montant remis","C"],["mobile","Mobile Money","Vérification visuelle par l’agent","M"],["wallet","Mini-wallet","Utiliser le crédit disponible","W"]].map(x=>`<button class="payment-method ${state.payment===x[0]?"selected":""}" data-payment="${x[0]}"><span>${x[3]}</span><strong>${x[1]}</strong><small>${x[2]}</small><i>${state.payment===x[0]?"✓":""}</i></button>`).join("")}</div><div class="payment-box">${paymentContent}</div><div class="checkout-actions"><button class="btn btn-ghost" data-sale-step="3">Retour</button><button class="btn btn-primary" data-complete-sale>Valider définitivement · ${money(trip.price)}</button></div></section>${journeySummary()}</div>`;
