  function performUiAction(message,target){
    if(/export|rapport pdf|manifeste pdf/i.test(message)){exportVisibleTable(message);toast("Fichier généré et téléchargé");return true}
    if(/impression|imprimer/i.test(message)){if(state.mecfBlocked){toast("Impression bloquée · transmission MECeF en échec depuis plus de 24 h");state.page="mecef";render();return true}window.print();return true}
    if(/justificatif/i.test(message)){const input=document.createElement("input");input.type="file";input.accept=".pdf,.png,.jpg,.jpeg";input.onchange=()=>toast(input.files?.[0]?`${input.files[0].name} ajouté`:"Aucun document sélectionné");input.click();return true}
    if(message==="Billet envoyé par WhatsApp"){window.open("https://wa.me/?text="+encodeURIComponent("Votre billet KORA EXPRESS KE-20260729-0842 est prêt."),"_blank","noopener");toast("Partage WhatsApp ouvert");return true}
    if(message.includes("Passagers incomplets")){document.querySelectorAll(".embedded-table tbody tr").forEach(row=>row.hidden=!/Manquant/i.test(row.textContent));toast("1 passager incomplet affiché");return true}
    if(message.includes("filtré")){const label=message.replace(" filtré","");document.querySelectorAll(".parcel-movement").forEach(row=>row.hidden=!row.textContent.includes(label));toast(`${label} affiché`);return true}
    if(message==="Filtres ouverts"){const anchor=target.closest(".section-intro");let panel=document.querySelector(".advanced-filters");if(panel){panel.remove();toast("Filtres refermés")}else{panel=document.createElement("div");panel.className="advanced-filters";panel.innerHTML='<label>Statut<select class="control"><option>Tous</option><option>En transit</option><option>À remettre</option><option>Incident</option></select></label><label>Origine<select class="control"><option>Toutes</option><option>Cotonou</option><option>Porto-Novo</option><option>Parakou</option></select></label><label>Période<input class="control" type="date" value="2026-07-29"></label><button class="btn btn-primary" data-toast="Filtres appliqués">Appliquer</button>';anchor?.after(panel);toast("Filtres avancés affichés")}return true}
    if(message==="Journal complet affiché"){const body=document.querySelector(".table-card tbody");if(body&&!body.dataset.expanded){body.dataset.expanded="true";[["CA-260729-0812","Vente billet KE 203","Espèces","6 000 FCFA","Confirmé","08:52"],["CA-260729-0798","Envoi colis KX-43496","Mobile Money","8 500 FCFA","Confirmé","08:31"],["CA-260729-0772","Vente billet KE 104","Mini-wallet","8 500 FCFA","Confirmé","08:08"]].forEach(row=>body.insertAdjacentHTML("beforeend",`<tr>${row.map((cell,i)=>`<td>${i===0?`<span class="cell-main">${cell}</span>`:i===4?`<span class="status navy">${cell}</span>`:cell}</td>`).join("")}<td><button class="row-action" data-toast="Écriture de caisse ouverte">→</button></td></tr>`));toast("3 écritures supplémentaires affichées")}return true}
    if(message.includes("ouvert")&&target.closest(".activity")){const routes=message.includes("Départ")?"departures":message.includes("CassKai")||message.includes("rapprochement")?"casskai":message.includes("Reversement")?"settlements":"parcels";state.page=routes;render();scrollTo(0,0);return true}
    if(message==="Écriture de caisse ouverte"){state.page="detail-cash";state.detailIndex=0;state.detailTab=0;render();scrollTo(0,0);return true}
    if(message==="Affectations enregistrées"){state.modal="edit";render();return true}
    if(message.includes("chargement ouvert")){document.querySelectorAll(".embedded-table tbody tr").forEach(row=>{if(/À scanner/.test(row.textContent)){row.lastElementChild.innerHTML='<button class="btn btn-primary" data-toast="Colis scanné et chargé">Scanner</button>'}});toast("Contrôle de chargement prêt");return true}
    if(message.includes("Manifeste d’embarquement préparé")){toast("Manifeste généré avec les 46 passagers embarqués");return true}
    if(message.includes("Contrôles frontière relancés")){document.querySelector(".manifest-check-card h3")?.replaceChildren("Contrôle en cours");toast("Vérification des documents relancée");return true}
    if(message.includes("Dossier de vente temporaire")){state.saleDraft=true;target.textContent="Enregistré ✓";toast("Dossier conservé dans cette session");return true}
    if(/actualisé|recalculée/i.test(message)){const scope=target.closest(".panel,.table-card,.search-route,.detail-grid")||document.querySelector(".content");scope?.classList.add("is-loading");setTimeout(()=>{scope?.classList.remove("is-loading");toast(message)},450);return true}
    return false;
  }
